// Implementation snippet: token + ACL check
function authorize(token, topic, operation) {
  const claims = decodeJWT(token);
  if (Date.now() >= claims.exp) return false;
  if (!claims.tenants.includes(claims.tenant)) return false;
  const acl = ACL_STORE[claims.tenant]?.[topic];
  if (!acl) return false;
  return acl.includes(operation);
}
```

